# Вариант Б: школа и турагентство. Формат задачи см. build.py
V = 'B'
TASKS = [
dict(n=1, pts=0.5, title='Допуск к экскурсии', topics='if / elif / else, in, and',
 text='В окне уже заданы список `groups` и три фразы: `go_msg`, `stay_msg`, `other_msg`. Вводятся номер класса и ответ родителей (`да` или `нет`).\n\nЕсли класс в списке и ответ `да`, напечатайте `go_msg`. Если класс в списке, но ответ другой, напечатайте `stay_msg`. Если класса нет в списке, напечатайте `other_msg`.',
 fin='Первая строка — класс, вторая — ответ.', fout='Одна из трёх фраз.',
 pre="groups = ['5А', '6Б', '7В']\ngo_msg = 'Едете на экскурсию'\nstay_msg = 'Остаётесь в школе'\nother_msg = 'Для вашего класса экскурсии нет'",
 inputs=[['5А','да'],['6Б','нет'],['8Г','да'],['7В','да'],['5А','нет'],['9Д','нет']],
 sol="cls = input()\nanswer = input()\n\nif cls in groups and answer == 'да':\n    print(go_msg)\nelif cls in groups:\n    print(stay_msg)\nelse:\n    print(other_msg)\n",
 hint='Сначала проверьте оба условия сразу через `and`, затем вторым шагом только «класс в списке», остальное — `else`.',
 idea='Три исхода — цепочка `if / elif / else`: класс в списке и ответ `да`; класс в списке и любой другой ответ; класса нет в списке.',
 steps=['`cls` и `answer` — две строки ввода. Слово `class` занято в Python, поэтому переменную называют иначе.','`cls in groups and answer == "да"` — оба условия верны одновременно.','`elif cls in groups` — сюда попадут только те, у кого ответ не `да`.','`else` — класса нет в списке.'],
 mist=['Поставили первой проверку `cls in groups`: «да» тогда никогда не дойдёт до своей ветки.','Назвали переменную `class`: это ключевое слово, будет `SyntaxError`.','Забыли кавычки у `да`: Python решит, что это переменная.']),
dict(n=2, pts=1, title='Хорошие оценки', topics='while True, break, split, список',
 text='Вводятся строки вида `ученик:балл` (балл — целое число), пока не будет введено слово `END`.\n\nНапечатайте список учеников, у которых балл **не ниже 8**, в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `ученик:балл`, последняя строка — `END`.', fout='Список имён в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Аня:9','Боря:5','Вера:8','END'],['END'],['Глеб:7','Даша:6','END'],['Егор:10','Жанна:8','Зоя:3','Иван:9','END'],['Коля:8','END']],
 sol="good = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, mark = line.split(':')\n    if int(mark) >= 8:\n        good.append(name)\n\nprint(good)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `name, mark = line.split(":")`. Балл — строка, нужен `int`. «Не ниже 8» — это `>=`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`good = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`name, mark = line.split(":")` — две части строки в две переменные.','`int(mark) >= 8` — «не ниже 8» включает сам восьмёрку.'],
 mist=['Список создан внутри цикла — в конце останется только последний ученик.','Не сделали `int(mark)`: сравнение строки `"9"` с числом — ошибка `TypeError`.','Поставили `>`: ученик с баллом ровно 8 пропадёт.']),
dict(n=3, pts=0.5, title='Новый кружок', topics='split(", "), not in, append',
 text='В первой строке названия кружков через «запятая + пробел». Во второй — название нового кружка.\n\nЕсли такого кружка ещё нет, добавьте его в конец списка. Напечатайте список.',
 fin='Первая строка — названия через `, `. Вторая — одно название.', fout='Список названий в квадратных скобках.',
 pre='',
 inputs=[['Шахматы, Танцы, Хор','Робототехника'],['Шахматы, Танцы','Танцы'],['Рисование','Рисование'],['Футбол, Плавание','Теннис'],['Хор','хор']],
 sol="clubs = input().split(', ')\nnew_club = input()\n\nif new_club not in clubs:\n    clubs.append(new_club)\n\nprint(clubs)\n",
 hint='Строку с названиями разбейте `split(", ")` (запятая и пробел). Проверка — `not in`, добавление — `append`.',
 idea='Превращаем строку в список, проверяем, нет ли там нового кружка, и добавляем при необходимости.',
 steps=['`input().split(", ")` — строка превращается в список названий.','`new_club not in clubs` — истина, если такого кружка в списке нет.','`clubs.append(new_club)` добавляет в конец и меняет сам список.','Печатаем в конце, чтобы вывод был и когда кружок уже был.'],
 mist=['`split()` без аргумента режет по пробелам, а запятые остаются в кусках.','`print` внутри `if`: если кружок уже есть, ничего не напечатается.','`clubs = clubs.append(...)` даёт `None`: `append` ничего не возвращает.']),
dict(n=4, pts=1, title='Недорогие туры', topics='два списка, range(len())',
 text='В первой строке названия туров через пробел, во второй — их цены (целые числа) в том же порядке. В третьей — бюджет.\n\nНапечатайте туры, цена которых **строго меньше** бюджета, каждый с новой строки в виде `тур цена`.',
 fin='Три строки: туры, цены, бюджет.', fout='Строки `тур цена` или пустой вывод.',
 pre='',
 inputs=[['Сочи Казань Алтай Крым','50000 30000 45000 60000','46000'],['А Б','100 200','50'],['Байкал','70000','70001'],['Тур1 Тур2 Тур3','10 20 30','30'],['Х У','5 5','6']],
 sol="tours = input().split()\nprices = input().split()\nbudget = int(input())\n\nfor i in range(len(tours)):\n    if int(prices[i]) < budget:\n        print(tours[i], prices[i])\n",
 hint='Туры и цены лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Цены — строки, для сравнения нужен `int`.',
 idea='Идём по номерам: по номеру берём и тур, и цену, сравниваем цену с бюджетом и печатаем обе.',
 steps=['`tours` и `prices` — списки **строк**; цену для сравнения берём как `int(prices[i])`.','`range(len(tours))` — номера 0, 1, 2, …','`int(prices[i]) < budget` — «строго меньше», то есть `<`.','`print(tours[i], prices[i])` с запятой печатает через пробел; цену печатаем как строку, `int` для вывода не нужен.'],
 mist=['`<=` вместо `<`: тур с ценой ровно в бюджет попадёт зря.','Сравнили `prices[i] < budget` без `int`: строка с числом — ошибка `TypeError`.','Напечатали только название или только цену, а нужно обе.']),
dict(n=5, pts=0.75, title='Страны только у Ани', topics='множества, разность',
 text='Две строки: страны, в которых побывала Аня, и страны, в которых побывал Борис (через пробел).\n\nНапечатайте через пробел страны, где была **только Аня**, в алфавитном порядке. Если таких нет, напечатайте пустую строку.',
 fin='Две строки, страны через пробел.', fout='Страны через пробел в алфавитном порядке или пустая строка.',
 pre='',
 inputs=[['Италия Испания Франция','Франция Греция'],['Египет','Египет'],['Чехия Польша','Литва'],['Турция Греция','Греция Турция Италия'],['Япония Китай Корея','Корея']],
 sol="anna = set(input().split())\nboris = set(input().split())\n\nprint(*sorted(anna - boris))\n",
 hint='Превратите обе строки во множества. «Только у Ани» — это разность `-`. Затем отсортируйте и распечатайте через `print(*...)`.',
 idea='Страны Ани минус страны Бориса: остаётся то, чего у Бориса нет.',
 steps=['`set(input().split())` — строка → список → множество.','`anna - boris` — элементы первого множества, которых нет во втором.','`sorted(...)` даёт список по алфавиту.','`print(*список)` печатает через пробел; для пустого списка получится пустая строка.'],
 mist=['`boris - anna`: порядок вычитания важен, получатся страны только Бориса.','`print(anna - boris)` печатает фигурные скобки и случайный порядок.','Забыли `sorted`: порядок стран может отличаться от ожидаемого.']),
dict(n=6, pts=1.25, title='Языки для поездки', topics='множества, разность и пересечение',
 text='Три строки с названиями языков через запятую **без пробела** (в названиях пробелы бывают): языки, которые знает Аня; языки, которые знает Борис; языки, нужные для поездки.\n\nНапечатайте, сколько нужных для поездки языков знает **Аня, но не знает Борис**.',
 fin='Три строки, языки через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Английский,Немецкий,Французский','Английский,Испанский','Английский,Немецкий,Французский,Итальянский'],['А б,В г','Д е','А б'],['Китайский','Китайский','Китайский'],['Польский,Чешский','Чешский','Польский,Чешский,Словацкий'],['Греческий','Турецкий','Арабский']],
 sol="anna = set(input().split(','))\nboris = set(input().split(','))\nneed = set(input().split(','))\n\nonly_anna = anna - boris\nprint(len(only_anna & need))\n",
 hint='Сначала найдите языки, которые знает только Аня (разность `-`), потом оставьте из них только нужные (пересечение `&`).',
 idea='Сначала разность «Аня минус Борис», затем пересечение с нужными языками.',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`anna - boris` — языки, которые знает Аня, но не Борис.','`only_anna & need` — из них только нужные для поездки.','`len(...)` — сколько их.'],
 mist=['`split()` вместо `split(",")`: названия с пробелом разорвутся.','`boris - anna`: получатся языки, которые знает Борис, но не Аня.','`|` вместо `&`: посчитаются все языки, а не только нужные.']),
dict(n=7, pts=0.75, title='Ученики с одной оценкой', topics='словарь, перебор ключей',
 text='В окне задан словарь `marks`: ученик → оценка за контрольную. Вводится оценка (целое число).\n\nНапечатайте учеников с этой оценкой, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — оценка (целое число).', fout='Имена по одному на строке или пустой вывод.',
 pre="marks = {'Аня': 5, 'Борис': 4, 'Вера': 5, 'Глеб': 3, 'Дарья': 4, 'Егор': 5}",
 inputs=[['5'],['4'],['3'],['2'],['10']],
 sol="mark = int(input())\n\nfor name in marks:\n    if marks[name] == mark:\n        print(name)\n",
 hint='Цикл `for name in marks` перебирает **ключи** (учеников). Оценка берётся как `marks[name]`. Введённая оценка — строка, нужен `int`.',
 idea='Идём по ученикам и печатаем тех, у кого оценка совпадает с введённой.',
 steps=['`mark = int(input())` — оценки в словаре числа, значит и введённую нужно сделать числом.','`for name in marks:` — переменная `name` по очереди получает каждого ученика.','`marks[name] == mark` — совпадение оценки.','Печатаем `name`, а не оценку.'],
 mist=['Забыли `int(...)`: сравнение `5 == "5"` даёт `False`, ничего не напечатается.','Напечатали `marks[name]`: получится оценка вместо имени.','Ждали, что цикл даст значения: он перебирает ключи.']),
dict(n=8, pts=1.25, title='Маршруты с хорошим сервисом', topics='словарь списков, min',
 text='В окне задан словарь `routes`: маршрут → список оценок пассажиров (от 1 до 5). Вводится минимальная допустимая оценка.\n\nНапечатайте маршруты, у которых **все** оценки **не ниже** введённой, каждый с новой строки, в порядке словаря.',
 fin='Одна строка — минимальная оценка (целое число).', fout='Названия маршрутов по одному на строке или пустой вывод.',
 pre="routes = {'Сочи': [4, 5, 3, 5], 'Байкал': [5, 5, 4, 5], 'Алтай': [3, 4, 4, 2], 'Крым': [4, 4, 5, 4]}",
 inputs=[['4'],['5'],['3'],['1'],['2']],
 sol="need = int(input())\n\nfor route in routes:\n    if min(routes[route]) >= need:\n        print(route)\n",
 hint='«Все оценки не ниже порога» — это то же, что «самая низкая оценка не ниже порога». Используйте `min`.',
 idea='Вместо проверки каждой оценки сравниваем с порогом минимум в списке.',
 steps=['`routes[route]` — список оценок маршрута.','`min(...)` — самая низкая оценка.','Если самая низкая не ниже порога, то и все остальные не ниже. «Не ниже» — это `>=`.','Печатаем **ключ** `route`, а не список.'],
 mist=['`max` вместо `min`: условие станет «хотя бы одна оценка не ниже порога».','`>` вместо `>=`: маршрут с минимумом ровно на пороге пропадёт.','Напечатали `routes[route]` — список оценок вместо названия.']),
dict(n=9, pts=1.5, title='Дни одной недели', topics='цикл, целочисленное деление',
 text='Дни года пронумерованы подряд: дни 1–7 — неделя 1, дни 8–14 — неделя 2 и так далее.\n\nПервая строка — номера дней через пробел. Вторая — номер недели. Напечатайте, сколько введённых дней приходится на эту неделю.',
 fin='Две строки: номера дней, номер недели.', fout='Одно число.',
 pre='',
 inputs=[['1 5 7 8 14 15','1'],['7 8 9 14 15','2'],['100 101 99','15'],['3 10 17','3'],['21 22','4'],['1 2 3 4 5 6 7 8','1'],['50','8'],['1 8 15 22 29','2']],
 sol="days = input().split()\nweek = int(input())\n\ncount = 0\nfor day in days:\n    if (int(day) - 1) // 7 + 1 == week:\n        count += 1\n\nprint(count)\n",
 hint='Номер недели для дня `d` — `(d - 1) // 7 + 1`. Счётчик создайте до цикла.',
 idea='Для каждого дня считаем номер его недели и сравниваем с введённым.',
 steps=['`int(day)` — дни нужны числами.','`(int(day) - 1) // 7 + 1`: день 7 даёт 6 // 7 = 0, неделя 1; день 8 даёт 7 // 7 = 1, неделя 2.','`count = 0` до цикла, `count += 1` на каждом подходящем.','Печатаем итог после цикла.'],
 mist=['`int(day) // 7 + 1` без `- 1`: день 7 уйдёт в неделю 2, а должен остаться в неделе 1.','Забыли `int`: `-` и `//` со строкой — ошибка.','Счётчик обнулили внутри цикла.'],
 trace='Проверка: день 7 → (7 - 1) // 7 + 1 = 0 + 1 = 1. День 8 → 7 // 7 + 1 = 2. День 14 → 13 // 7 + 1 = 2. День 15 → 14 // 7 + 1 = 3.'),
dict(n=10, pts=1.5, title='Самый дешёвый маршрут', topics='while True, словарь-накопитель, минимум',
 text='Вводятся строки вида `маршрут,сумма` (сумма — целое **положительное** число: стоимость одной продажи), пока не будет введено слово `END`. Один маршрут может встретиться несколько раз.\n\nНайдите маршрут с **наименьшей суммарной** выручкой. Напечатайте его название и сумму через пробел. Гарантируется, что есть хотя бы одна строка. Если у нескольких одинаковый минимум — выведите того, кто встретился раньше.',
 fin='Строки `маршрут,сумма`, последняя строка — `END`.', fout='Название и сумма через пробел.',
 pre='',
 inputs=[['Сочи,50','Алтай,20','Сочи,40','Алтай,15','Байкал,100','END'],['Крым,5','END'],['А,10','Б,10','END'],['Х,100','У,50','У,60','END'],['Тур,7','Круиз,3','Тур,2','Круиз,9','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    route, price = line.split(',')\n    if route in totals:\n        totals[route] += int(price)\n    else:\n        totals[route] = int(price)\n\nworst = ''\nworst_sum = None\nfor route in totals:\n    if worst_sum is None or totals[route] < worst_sum:\n        worst_sum = totals[route]\n        worst = route\n\nprint(worst, worst_sum)\n",
 hint='Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите минимум. Стартовое значение для минимума — `None`: первое же значение его заменит. Для строгого сравнения берите `<`.',
 idea='Сначала собираем словарь «маршрут → выручка», потом ищем ключ с наименьшим значением.',
 steps=['`totals = {}` — до цикла.','Если маршрут уже есть в словаре, прибавляем: `totals[route] += int(price)`, иначе создаём запись.','Для минимума нельзя стартовать с `0`: любая сумма больше нуля и не заменит его. Поэтому берём `None` и первое же значение его заменяет.','`<` (строго) оставляет первого из равных, как требует условие.','`print(worst, worst_sum)` с запятой печатает через пробел.'],
 mist=['Стартовое значение `0`: ни одна сумма не окажется меньше нуля, и ответом будет пустое имя.','`min(totals)` без `key` берёт минимум **по алфавиту названий**, а не по сумме.','`<=` вместо `<`: при равных суммах выберется последний, а не первый.','Забыли `int(price)`: строки склеиваются.'],
 trace='Сочи: 50, затем 40 → 90. Алтай: 20, затем 15 → 35. Байкал: 100. Минимум 35 у Алтая. Словарь по шагам: `{Сочи: 50}` → `{Сочи: 50, Алтай: 20}` → `{Сочи: 90, Алтай: 20}` → …'),
]
